 ("story/bmw-30s-story-vertical.mp4", "story/output/bmw-30s-story-vertical.mp4"),
]
def new_of(old):
    for a, b in MAP:
        if old == a or (a.endswith('/') and old.startswith(a)):
            return b + old[len(a):]
