# 2. rewrite HTML attribute links (resolve against OLD location, re-relativise to NEW)
attr = re.compile(r'((?:src|href|poster)=")([^"#:?]+)((?:[#?][^"]*)?")')
def fix_html(old_path, text):
    od = os.path.dirname(old_path); nd = os.path.dirname(moves[old_path])
