/* Memtrack design tokens
 * Palette inspired by BMW's public brand and BMW M colours (not official BMW tokens).
 * Rule of thumb: depth of blue = strength of the signal.
 *   Principles (L1) = deep blue · Evidence (L2) = BMW blue · Signals (L3) = light M blue.
 * Use the semantic tokens (--mt-*) in components, never the raw palette.
 */
@import url("https://fonts.googleapis.com/css2?family=Barlow:wght@400;500;600;700&family=Barlow+Semi+Condensed:wght@500;600;700&family=IBM+Plex+Mono:wght@400;500&display=swap");

:root {
  /* raw palette */
  --bmw-blue: #1c69d4;        /* BMW digital blue: primary action */
  --bmw-blue-dark: #0f4fa8;
  --m-dark-blue: #16588e;     /* BMW M dark blue: principles layer */
  --m-light-blue: #5fb4ff;    /* BMW M light blue: signals layer (tuned for contrast) */
  --m-red: #e22718;           /* BMW M red: human decision points, used sparingly */
  --carbon: #16171a;          /* near-black */
  --steel-900: #0b1626; --steel-800: #142236; --steel-700: #1e2f47;
  --gray-600: #5b6676; --gray-400: #98a2b3; --gray-200: #dfe4ec; --gray-100: #eef1f6; --white: #ffffff;

  /* semantic: surfaces and text (light) */
  --mt-bg: #f3f5f9;
  --mt-surface: #ffffff;
  --mt-surface-2: #f7f9fc;
  --mt-ink: #121722;
  --mt-muted: #5b6676;
  --mt-line: #dfe4ec;
  --mt-primary: var(--bmw-blue);
  --mt-primary-ink: #ffffff;
  --mt-primary-soft: #e8f0fc;
  --mt-focus: #1c69d4;

  /* semantic: the three layers */
  --mt-l1: #16588e;  --mt-l1-soft: #e3edf6;   /* principles */
  --mt-l2: #1c69d4;  --mt-l2-soft: #e8f0fc;   /* evidence */
  --mt-l3: #2f95e6;  --mt-l3-soft: #e5f3fe;   /* signals */

  /* semantic: who decides */
  --mt-auto: #5b6676; --mt-auto-soft: #eef1f6;      /* AI on its own */
  --mt-propose: #1c69d4; --mt-propose-soft: #e8f0fc; /* AI proposes */
  --mt-human: #e22718; --mt-human-soft: #fdecea;     /* human only */

  /* semantic: status */
  --mt-ok: #1e8e3e;   --mt-ok-soft: #e6f4ea;     /* approved / kept */
  --mt-wait: #b26b00; --mt-wait-soft: #fdf2df;   /* postponed / pending */
  --mt-bad: #c5221f;  --mt-bad-soft: #fce8e6;    /* rejected / conflict */
