/* Memtrack prototype shell: shared by every view.
 * - Builds the sidebar and top bar around <main id="view">.
 * - Holds the scope (model, market) and the PM's weight edits in localStorage.
 * - Exposes the scoring engine so every view ranks requirements the same way.
 * Usage in a view: set <body data-view="cockpit">, include sample-data.js, then app.js,
 * then the view's own script, and listen: MT.onScope(render); render();
 */
(function () {
  const D = window.MT_DATA;
  const NAV = [
    { id: "cockpit", label: "Cockpit", href: "cockpit.html", icon: "M3 13h8V3H3zm10 8h8V11h-8zM3 21h8v-6H3zm10-18v6h8V3z" },
    { id: "requirements", label: "Requirements", href: "requirements.html", icon: "M4 6h16M4 12h16M4 18h10" },
    { id: "lineage", label: "Lineage", href: "lineage.html", icon: "M5 4v6a4 4 0 0 0 4 4h6m0 0-3-3m3 3-3 3M5 20h.01" },
    { id: "weights", label: "Weights", href: "weights.html", icon: "M4 21v-7M4 10V3M12 21v-9M12 8V3M20 21v-5M20 12V3M1 14h6M9 8h6M17 16h6" },
    { id: "principles", label: "Principles", href: "principles.html", icon: "M12 2 3 6v6c0 5 4 9 9 10 5-1 9-5 9-10V6z" },
    { id: "hitl", label: "Human in the loop", href: "hitl.html", icon: "M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8zm-8 9a8 8 0 0 1 16 0" },
    { id: "memory", label: "Decision memory", href: "memory.html", icon: "M12 8v4l3 2M3 12a9 9 0 1 0 3-6.7L3 8m0-5v5h5" },
    { id: "gaps", label: "What we don't know", href: "gaps.html", icon: "M12 9v4m0 4h.01M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z" }
  ];

  const store = {
    get(k, d) { try { const v = localStorage.getItem("mt:" + k); return v === null ? d : JSON.parse(v); } catch (e) { return d; } },
    set(k, v) { try { localStorage.setItem("mt:" + k, JSON.stringify(v)); } catch (e) { /* private mode: keep in memory only */ } }
  };

  const scope = { model: store.get("model", "G70"), market: store.get("market", "ALL") };
  const listeners = [];

  function el(tag, attrs, ...kids) {
    const n = document.createElement(tag);
    for (const [k, v] of Object.entries(attrs || {})) {
      if (k === "class") n.className = v;
      else if (k === "html") n.innerHTML = v;
      else if (k.startsWith("on")) n.addEventListener(k.slice(2), v);
      else if (v !== false && v != null) n.setAttribute(k, v === true ? "" : v);
    }
    for (const c of kids.flat()) if (c != null && c !== false) n.append(c.nodeType ? c : String(c));
    return n;
  }
  const svg = (d) => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${d}"/></svg>`;

  /* ---------- weights (with PM edits) ---------- */
  function layerWeights(model) {
    const edits = store.get("layerWeights", {});
    return Object.assign({}, D.layerWeights[model], edits[model] || {});
  }
  function sourceWeight(sourceId, model) {
    const edits = store.get("sourceWeights", {});
    if (edits[model] && edits[model][sourceId] != null) return edits[model][sourceId];
    const o = (D.sourceOverrides[model] || {})[sourceId];
    if (o != null) return o;
    return D.sources.find((s) => s.id === sourceId).weight;
  }
  function setLayerWeight(model, layer, v) {
    const e = store.get("layerWeights", {}); e[model] = Object.assign({}, e[model], { [layer]: v }); store.set("layerWeights", e); emit();
  }
  function setSourceWeight(model, src, v) {
    const e = store.get("sourceWeights", {}); e[model] = Object.assign({}, e[model], { [src]: v }); store.set("sourceWeights", e); emit();
  }
  function resetWeights(model) {
    const a = store.get("layerWeights", {}); delete a[model]; store.set("layerWeights", a);
    const b = store.get("sourceWeights", {}); delete b[model]; store.set("sourceWeights", b); emit();
  }

  /* ---------- scoring engine ----------
   * L2 and L3 = weighted average of source signals inside the layer.
   * L1 = principle fit: +1 supporting principle -> 1.0, conflicting -> 0.0, none -> 0.5.
   * total = sum(layer weight × layer score) / sum(layer weights), then × market support factor.
   * Market support: volume-weighted share of markets in favour (the 7 Series size rule).
   */
  function score(req, overrides) {
    const model = req.model;
    const lw = Object.assign({}, layerWeights(model), (overrides && overrides.layer) || {});
    const sw = (id) => (overrides && overrides.source && overrides.source[id] != null) ? overrides.source[id] : sourceWeight(id, model);
    const byLayer = {};
    for (const L of ["L2", "L3"]) {
      const srcs = D.sources.filter((s) => s.layer === L);
      const wsum = srcs.reduce((a, s) => a + sw(s.id), 0) || 1;
      byLayer[L] = srcs.reduce((a, s) => a + sw(s.id) * (req.signals[s.id] || 0), 0) / wsum;
    }
    const fits = Object.values(req.principleFit || {});
    const sup = fits.filter((f) => f > 0).length, con = fits.filter((f) => f < 0).length;
    byLayer.L1 = fits.length ? 0.5 + 0.5 * (sup - con) / fits.length : 0.5;
    const lsum = (lw.L1 + lw.L2 + lw.L3) || 1;
    const base = (lw.L1 * byLayer.L1 + lw.L2 * byLayer.L2 + lw.L3 * byLayer.L3) / lsum;
    const vol = D.marketVolume[model] || {};
    let pro = 0, contra = 0;
    for (const [m, s] of Object.entries(req.markets || {})) { if (s === "+") pro += vol[m] || 0; if (s === "-") contra += vol[m] || 0; }
    const marketFactor = 0.85 + 0.15 * (pro - contra) / 100 * 2;
    const total = Math.max(0, Math.min(1, base * marketFactor));
    return { total, byLayer, marketPro: pro, marketContra: contra, principleConflict: con > 0 };
  }
  function ranked(model, overrides) {
    return D.requirements.filter((r) => r.model === model)
      .map((r) => Object.assign({ score: score(r, overrides) }, r))
      .sort((a, b) => b.score.total - a.score.total);
  }

  /* ---------- requirement status edits (approve / edit / postpone / reject / keep) ---------- */
  function statusOf(req) { return store.get("status", {})[req.id] || req.status; }
  function decide(reqId, action, reason) {
    const st = store.get("status", {});
    const map = { approve: "approved", keep: "approved", postpone: "postponed", reject: "rejected", edit: "edited" };
    st[reqId] = map[action] || action; store.set("status", st);
    const log = store.get("decisions", []);
    log.push({ id: "D-" + (100 + log.length), req: reqId, action, by: "You (PM)", at: new Date().toISOString().slice(0, 16), reason: reason || "", snapshot: "#local", edited: false });
    store.set("decisions", log); emit();
  }
  function decisions() { return D.decisions.concat(store.get("decisions", [])); }

  /* ---------- shell ---------- */
  function emit() { listeners.forEach((f) => f(scope)); }
  function onScope(f) { listeners.push(f); }
  function setScope(k, v) { scope[k] = v; store.set(k, v); emit(); }
  function modelName(id) { return (D.models.find((m) => m.id === id) || {}).name || id; }

  function buildShell() {
    const active = document.body.dataset.view;
    const main = document.getElementById("view");
    const shell = el("div", { class: "mt-shell" });
    const side = el("aside", { class: "mt-side", "aria-label": "Main navigation" },
      el("a", { class: "mt-brand", href: "../index.html", html: '<img src="../../branding/logo-mark.svg" alt="" width="30" height="30"><span>Mem<b>track</b></span>' }),
      el("nav", {}, NAV.map((n) => el("a", { href: n.href, class: "mt-nav" + (n.id === active ? " is-active" : ""), "aria-current": n.id === active ? "page" : false, html: svg(n.icon) + `<span>${n.label}</span>` }))),
      el("div", { class: "mt-side-foot" }, el("span", { class: "mt-badge mt-badge--sample" }, D.meta.isSample ? "Sample data" : "Real data"), el("small", {}, D.meta.label))
    );
    const modelSel = el("select", { id: "mt-model", "aria-label": "Model", onchange: (e) => setScope("model", e.target.value) },
      D.models.map((m) => el("option", { value: m.id, selected: m.id === scope.model }, `${m.name} (${m.id})`)));
    const marketSel = el("select", { id: "mt-market", "aria-label": "Market", onchange: (e) => setScope("market", e.target.value) },
      el("option", { value: "ALL", selected: scope.market === "ALL" }, "All markets"),
      D.markets.map((m) => el("option", { value: m.id, selected: m.id === scope.market }, m.name)));
    const theme = el("button", { class: "mt-btn mt-btn--ghost", type: "button", "aria-label": "Toggle colour theme", onclick: () => {
      const r = document.documentElement; const dark = r.dataset.theme ? r.dataset.theme === "dark" : matchMedia("(prefers-color-scheme: dark)").matches;
      r.dataset.theme = dark ? "light" : "dark"; store.set("theme", r.dataset.theme); } }, "◐ Theme");
    const top = el("header", { class: "mt-top" },
      el("div", { class: "mt-top-title" }, el("h1", {}, document.title.replace(/ · Memtrack$/, "")), el("p", { class: "mt-sub" }, main.dataset.subtitle || "")),
      el("div", { class: "mt-scope" }, el("label", {}, "Model ", modelSel), el("label", {}, "Market ", marketSel), theme,
        el("span", { class: "mt-user", title: "Signed in as product manager" }, "PM"))
    );
    if (D.meta.isSample) top.append(el("div", { class: "mt-banner", role: "note" }, "⚑ " + D.meta.label + ". Swap in real data via data/prototype/memtrack-data.js."));
    const wrap = el("div", { class: "mt-content" });
    main.replaceWith(shell); shell.append(side, wrap); wrap.append(top, main);
    const t = store.get("theme", null); if (t) document.documentElement.dataset.theme = t;
  }

  window.MT = { data: D, el, svg, scope, onScope, setScope, modelName, score, ranked, layerWeights, sourceWeight, setLayerWeight, setSourceWeight, resetWeights, statusOf, decide, decisions, store };
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", buildShell); else buildShell();
})();

/* Memtrack prototype: shared layout and components. Colours come only from branding/tokens.css. */
* { box-sizing: border-box; }
html, body { margin: 0; }
body { background: var(--mt-bg); color: var(--mt-ink); font-family: var(--mt-font); font-size: 15px; line-height: 1.5; }
a { color: var(--mt-primary); }
:focus-visible { outline: 2px solid var(--mt-focus); outline-offset: 2px; border-radius: 4px; }
h1, h2, h3, h4 { font-family: var(--mt-font-head); margin: 0; line-height: 1.15; text-wrap: balance; }
p { margin: 0; }
.num, td.num { font-variant-numeric: tabular-nums; }
@media (prefers-reduced-motion: reduce) { * { transition: none !important; animation: none !important; } }

/* ---------- shell ---------- */
.mt-shell { display: grid; grid-template-columns: 236px minmax(0, 1fr); min-height: 100vh; }
.mt-side { background: var(--steel-900); color: #cfd8e6; padding: 18px 12px; display: flex; flex-direction: column; gap: 18px; position: sticky; top: 0; height: 100vh; }
.mt-brand { display: flex; align-items: center; gap: 10px; color: #fff; text-decoration: none; font-family: var(--mt-font-head); font-size: 1.35rem; font-weight: 700; padding: 0 6px; }
.mt-brand b { color: var(--m-light-blue); font-weight: 700; }
.mt-side nav { display: grid; gap: 2px; }
.mt-nav { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: var(--mt-r-sm); color: #b8c4d6; text-decoration: none; font-weight: 500; }
.mt-nav svg { width: 18px; height: 18px; flex: none; }
.mt-nav:hover { background: rgba(255,255,255,.06); color: #fff; }
.mt-nav.is-active { background: var(--bmw-blue); color: #fff; }
.mt-side-foot { margin-top: auto; display: grid; gap: 6px; padding: 0 6px; }
.mt-side-foot small { color: #8291a8; font-size: .75rem; }
.mt-content { min-width: 0; display: flex; flex-direction: column; }
.mt-top { position: sticky; top: 0; z-index: 10; background: color-mix(in srgb, var(--mt-bg) 92%, transparent); backdrop-filter: blur(6px); border-bottom: 1px solid var(--mt-line); padding: 14px 24px 10px; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 6px 16px; align-items: center; }
.mt-top h1 { font-size: 1.6rem; }
.mt-sub { color: var(--mt-muted); font-size: .92rem; }
.mt-scope { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; justify-content: flex-end; }
.mt-scope label { font-size: .8rem; color: var(--mt-muted); display: flex; gap: 6px; align-items: center; }
select, input[type="text"], textarea { font: inherit; color: var(--mt-ink); background: var(--mt-surface); border: 1px solid var(--mt-line); border-radius: var(--mt-r-sm); padding: 6px 10px; }
textarea { width: 100%; min-height: 70px; resize: vertical; }
.mt-user { width: 32px; height: 32px; border-radius: 50%; display: grid; place-items: center; background: var(--mt-human); color: #fff; font-weight: 700; font-size: .8rem; }
.mt-banner { grid-column: 1 / -1; font-size: .78rem; color: var(--mt-wait); background: var(--mt-wait-soft); border-radius: var(--mt-r-sm); padding: 4px 10px; justify-self: start; }
main#view { padding: 22px 24px 60px; display: grid; gap: 18px; align-content: start; }
@media (max-width: 900px) {
  .mt-shell { grid-template-columns: minmax(0, 1fr); }
  .mt-side { position: static; height: auto; flex-direction: row; flex-wrap: wrap; align-items: center; padding: 10px 12px; gap: 10px; }
  .mt-side nav { display: flex; flex-wrap: wrap; gap: 4px; }
  .mt-nav span { font-size: .85rem; }
  .mt-side-foot { display: none; }
  .mt-top { grid-template-columns: minmax(0, 1fr); padding: 12px 16px; }
  .mt-scope { justify-content: flex-start; }
  main#view { padding: 16px 16px 48px; }
}

/* ---------- layout helpers ---------- */
.grid { display: grid; gap: 14px; }
.g2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.g3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.g4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.g-main { grid-template-columns: minmax(0, 2fr) minmax(0, 1fr); }
@media (max-width: 1100px) { .g4 { grid-template-columns: repeat(2, minmax(0, 1fr)); } .g-main { grid-template-columns: minmax(0, 1fr); } }
@media (max-width: 640px) { .g2, .g3, .g4 { grid-template-columns: minmax(0, 1fr); } }
.row { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.spread { display: flex; justify-content: space-between; align-items: center; gap: 10px; flex-wrap: wrap; }
.muted { color: var(--mt-muted); }
.small { font-size: .85rem; }

/* ---------- cards ---------- */
.card { background: var(--mt-surface); border: 1px solid var(--mt-line); border-radius: var(--mt-r-lg); padding: 16px 18px; display: grid; gap: 10px; align-content: start; min-width: 0; box-shadow: var(--mt-shadow); }
.card > h2, .card-title { font-size: 1.1rem; font-weight: 600; }
.card-kicker { font-family: var(--mt-font-mono); font-size: .7rem; letter-spacing: .1em; text-transform: uppercase; color: var(--mt-muted); }
.card--l1 { border-top: 4px solid var(--mt-l1); } .card--l2 { border-top: 4px solid var(--mt-l2); } .card--l3 { border-top: 4px solid var(--mt-l3); }
.card--human { border-left: 4px solid var(--mt-human); }
.kpi { display: grid; gap: 2px; }
.kpi b { font-family: var(--mt-font-head); font-size: var(--mt-fs-2xl); font-weight: 700; line-height: 1; font-variant-numeric: tabular-nums; }
.kpi span { font-size: .82rem; color: var(--mt-muted); }

/* ---------- badges ---------- */
.mt-badge { display: inline-flex; align-items: center; gap: 4px; font-size: .72rem; font-weight: 600; padding: 2px 8px; border-radius: 99px; white-space: nowrap; background: var(--mt-surface-2); color: var(--mt-muted); border: 1px solid var(--mt-line); }
.mt-badge--sample { background: var(--mt-wait-soft); color: var(--mt-wait); border-color: transparent; justify-self: start; }
.mt-badge--l1 { background: var(--mt-l1-soft); color: var(--mt-l1); border-color: transparent; }
.mt-badge--l2 { background: var(--mt-l2-soft); color: var(--mt-l2); border-color: transparent; }
.mt-badge--l3 { background: var(--mt-l3-soft); color: var(--mt-l3); border-color: transparent; }
.mt-badge--auto { background: var(--mt-auto-soft); color: var(--mt-auto); border-color: transparent; }
.mt-badge--propose { background: var(--mt-propose-soft); color: var(--mt-propose); border-color: transparent; }
.mt-badge--human { background: var(--mt-human-soft); color: var(--mt-human); border-color: transparent; }
.mt-badge--approved, .mt-badge--ok { background: var(--mt-ok-soft); color: var(--mt-ok); border-color: transparent; }
.mt-badge--postponed, .mt-badge--wait, .mt-badge--needs-engineering, .mt-badge--edited { background: var(--mt-wait-soft); color: var(--mt-wait); border-color: transparent; }
.mt-badge--rejected, .mt-badge--bad { background: var(--mt-bad-soft); color: var(--mt-bad); border-color: transparent; }
.mt-badge--proposed, .mt-badge--draft { background: var(--mt-draft-soft); color: var(--mt-draft); border-color: transparent; }
.mt-badge--gate { background: var(--mt-human); color: #fff; border-color: transparent; font-family: var(--mt-font-mono); }
.mt-badge--eu { color: var(--mt-eu); } .mt-badge--cn { color: var(--mt-cn); } .mt-badge--us { color: var(--mt-us); } .mt-badge--jp { color: var(--mt-jp); }

/* ---------- buttons ---------- */
.mt-btn { font: inherit; font-weight: 600; font-size: .88rem; padding: 6px 12px; border-radius: var(--mt-r-sm); border: 1px solid var(--mt-line); background: var(--mt-surface); color: var(--mt-ink); cursor: pointer; }
.mt-btn:hover { border-color: var(--mt-primary); }
.mt-btn--primary { background: var(--mt-primary); color: var(--mt-primary-ink); border-color: var(--mt-primary); }
.mt-btn--ghost { background: transparent; }
.mt-btn--ok { color: var(--mt-ok); border-color: var(--mt-ok); }
.mt-btn--wait { color: var(--mt-wait); border-color: var(--mt-wait); }
.mt-btn--bad { color: var(--mt-bad); border-color: var(--mt-bad); }

/* ---------- tables ---------- */
.tbl { overflow-x: auto; border: 1px solid var(--mt-line); border-radius: var(--mt-r-md); background: var(--mt-surface); }
table { border-collapse: collapse; width: 100%; font-size: .9rem; }
th, td { text-align: left; padding: 9px 12px; border-bottom: 1px solid var(--mt-line); vertical-align: top; }
th { font-family: var(--mt-font-head); font-weight: 600; font-size: .8rem; text-transform: uppercase; letter-spacing: .04em; color: var(--mt-muted); background: var(--mt-surface-2); }
tr:last-child td { border-bottom: 0; }
tbody tr[tabindex]:hover { background: var(--mt-surface-2); cursor: pointer; }
tr.is-selected td { background: var(--mt-primary-soft); }

/* ---------- bars ---------- */
.bar { height: 8px; border-radius: 99px; background: var(--mt-line); overflow: hidden; display: flex; }
.bar i { display: block; height: 100%; }
.bar i.l1 { background: var(--mt-l1); } .bar i.l2 { background: var(--mt-l2); } .bar i.l3 { background: var(--mt-l3); }
.bar i.primary { background: var(--mt-primary); } .bar i.ok { background: var(--mt-ok); } .bar i.bad { background: var(--mt-bad); }

/* ---------- range sliders ---------- */
input[type="range"] { width: 100%; accent-color: var(--mt-primary); }

/* ---------- drawer / panel ---------- */
.panel { background: var(--mt-surface); border: 1px solid var(--mt-line); border-radius: var(--mt-r-lg); padding: 16px 18px; display: grid; gap: 12px; position: sticky; top: 96px; }
.callout { border-radius: var(--mt-r-md); padding: 10px 12px; font-size: .9rem; }
.callout--warn { background: var(--mt-wait-soft); color: var(--mt-ink); border-left: 3px solid var(--mt-wait); }
.callout--bad { background: var(--mt-bad-soft); border-left: 3px solid var(--mt-bad); }
.callout--info { background: var(--mt-primary-soft); border-left: 3px solid var(--mt-primary); }
.callout--human { background: var(--mt-human-soft); border-left: 3px solid var(--mt-human); }
.empty { color: var(--mt-muted); font-style: italic; padding: 12px; }

