  ["Over-the-air updates for more features", "Digital", "Owners want new functions after purchase without a workshop visit.", 15],
];

const SPLIT: Record<SeriesId, Partial<Record<MarketId | "OTHER", number>>> = {
  F70: { EU: 0.62, JP: 0.28, OTHER: 0.1 },
  G60: { US: 0.7, EU: 0.12, JP: 0.06, OTHER: 0.12 },
  G70: { US: 0.74, EU: 0.08, JP: 0.06, OTHER: 0.12 },
};

const NAMES: Record<SeriesId, string> = { F70: "1 Series", G60: "5 Series", G70: "7 Series" };

function requestsFor(series: SeriesId, factor: number): FeatureRequest[] {
  return ROWS.map(([title, category, summary, base], i) => {
    const mentions = Math.round(base * factor);
    const byMarket = Object.fromEntries(
      Object.entries(SPLIT[series]).map(([m, share]) => [m, Math.round(mentions * (share ?? 0))]),
    );
    const wants = Math.round(mentions * 0.5);
    const difficult = Math.round(mentions * 0.3);
    return {
      id: `${series}-R${String(i + 1).padStart(2, "0")}`,
      series,
      title,
      category,
      summary,
      mentions,
      byMarket,
      types: { wants, difficult, defect: mentions - wants - difficult },
      sources: [
        { name: "Owner reviews", count: Math.round(mentions * 0.6) },
        { name: "Customer care", count: Math.round(mentions * 0.4) },
      ],
      quotes: [],
      taxonomy: [`Example topic ${i + 1}`],
      relatedOptions: [],
    };
  });
}

function series(id: SeriesId, factor: number): SeriesData {
  const total = Math.round(900 * factor);
  return {
    id,
    name: NAMES[id],
    feedbackByMarket: Object.fromEntries(Object.entries(SPLIT[id]).map(([m, s]) => [m, Math.round(total * (s ?? 0))])),
    requests: requestsFor(id, factor),
    strengths: [
      { title: "Driving pleasure", mentions: Math.round(140 * factor) },
      { title: "Exterior design", mentions: Math.round(110 * factor) },
      { title: "Seat comfort", mentions: Math.round(80 * factor) },
    ],
    studies: [],
    sales: [],
    options: [],
  };
}

export const EXAMPLE_PIPELINE: PipelineData = {
  origin: "example",
  generatedAt: "2026-10-10T00:00:00.000Z",
  series: [series("F70", 0.8), series("G60", 1.2), series("G70", 1)],
};

/* Server-only loader: the local BMW-derived file when it exists, otherwise the example set.
 * readFileSync at module scope runs once and is prerendered (see Next docs: caching → predictable values).
 */
import fs from "node:fs";
import path from "node:path";
import { EXAMPLE_PIPELINE } from "./example";
import type { PipelineData, SeriesId } from "./types";

const LOCAL_FILE = path.join(process.cwd(), "data-local", "pipeline.json");

function load(): PipelineData {
  try {
    return JSON.parse(fs.readFileSync(LOCAL_FILE, "utf-8")) as PipelineData;
  } catch {
    return EXAMPLE_PIPELINE;
  }
}

const DATA = load();

export const pipelineOrigin = () => DATA.origin;
export const seriesData = (id: SeriesId) => DATA.series.find((s) => s.id === id) ?? EXAMPLE_PIPELINE.series.find((s) => s.id === id)!;

/* Pipeline logic: market scoping, urgency, PM decisions, profile building and the layer score.
 * Pure functions, shared by the client components. Deterministic: the same decisions always build the same profiles.
 */
import type { MarketScope } from "@/lib/dashboard-data";
import type { SeriesConfig } from "./series";
import type { Category, FeatureRequest, SeriesData } from "./types";

/* ---------- scope + urgency ---------- */

/** Feedback records for this series in the chosen market; 0 means we have no comments there. */
export function marketVolume(data: SeriesData, scope: MarketScope): number {
  if (scope === "ALL") return Object.values(data.feedbackByMarket).reduce((a, b) => a + (b ?? 0), 0);
  return data.feedbackByMarket[scope] ?? 0;
}

/** Mentions of a request in scope. Falls back to all markets when the market has no comments at all. */
export function scopedMentions(req: FeatureRequest, scope: MarketScope, fallback: boolean): number {
  if (scope === "ALL" || fallback) return req.mentions;
  return req.byMarket[scope] ?? 0;
}

export type Urgency = "high" | "medium" | "low";
export const URGENCY_RULE = { high: 50, medium: 20 } as const;
export const urgencyOf = (mentions: number): Urgency =>
  mentions >= URGENCY_RULE.high ? "high" : mentions >= URGENCY_RULE.medium ? "medium" : "low";

/* ---------- PM decisions ---------- */

export interface Decision {
  requestId: string;
  title: string;
  action: "keep" | "reject";
  /** Required for a reject. */
  reason?: string;
  by: string;
  at: string;
}

export type Decisions = Record<string, Decision>;

export const REJECT_REASONS = [
  "Conflicts with a principle (L1)",
  "Too costly for the benefit",
  "Already on the option list",
  "Too few customers ask for it",
  "Not right for this market",
] as const;

/* ---------- profiles ---------- */

export interface Profile {
  id: string;
  name: string;
  tagline: string;
  requests: (FeatureRequest & { scoped: number })[];
  why: string[];
  score: { l1: number; l2: number; l3: number | null; total: number };
}

interface Archetype {
  id: string;
  name: string;
  tagline: string;
  /** Higher = picked first. */
  rank: (r: FeatureRequest) => number;
}

const fixShare = (r: FeatureRequest) => (r.types.difficult + r.types.defect) / Math.max(1, r.types.wants + r.types.difficult + r.types.defect);
const inCats = (cats: Category[]) => (r: FeatureRequest) => (cats.includes(r.category) ? 1 : 0);

const ARCHETYPES: Archetype[] = [
  {
    id: "fix",
    name: "Fix the basics",
    tagline: "Remove what annoys today's owners before adding anything new.",
    rank: (r) => fixShare(r),
  },
  {
    id: "tech",
    name: "Tech-forward",
    tagline: "Lead on software, assistance and powertrain.",
    rank: inCats(["Digital", "Powertrain"]),
  },
  {
    id: "comfort",
    name: "Comfort & craft",
    tagline: "A calmer, better-made cabin and a cleaner design.",
    rank: inCats(["Interior", "Exterior"]),
  },
];

const MAX_PER_PROFILE = 6;
export const MIN_KEPT_TO_BUILD = 3;

export function buildProfiles(
  kept: FeatureRequest[],
  cfg: SeriesConfig,
  scope: MarketScope,
  fallback: boolean,
  social: Record<string, number> | null,
): Profile[] {
  const scopedKept = kept.map((r) => ({ ...r, scoped: scopedMentions(r, scope, fallback) }));
  const keptTotal = scopedKept.reduce((a, r) => a + r.scoped, 0) || 1;

  return ARCHETYPES.map((a) => {
    const picked = [...scopedKept]
      .sort((x, y) => a.rank(y) - a.rank(x) || y.scoped - x.scoped)
      .slice(0, Math.min(MAX_PER_PROFILE, Math.max(MIN_KEPT_TO_BUILD, Math.ceil(scopedKept.length * 0.6))))
      .sort((x, y) => y.scoped - x.scoped);

    const covered = picked.reduce((s, r) => s + r.scoped, 0);
    const inFocus = picked.filter((r) => cfg.focus.includes(r.category)).length;
    const l1 = 0.5 + 0.5 * (inFocus / Math.max(1, picked.length));
    const l2 = covered / keptTotal;
    const l3 = social ? social[a.id] ?? null : null;
    const w3 = l3 === null ? 0 : cfg.l3Weight;
    const w1 = 0.45 * (1 - w3);
    const w2 = 1 - w1 - w3;
    const total = w1 * l1 + w2 * l2 + w3 * (l3 ?? 0);

    const cats = [...new Set(picked.map((r) => r.category))];
    const left = scopedKept.filter((r) => !picked.includes(r)).sort((x, y) => y.scoped - x.scoped);
    const why = [
      `Covers ${covered.toLocaleString("en")} customer mentions, ${Math.round(l2 * 100)}% of everything you kept (L2).`,
      `${inFocus} of ${picked.length} requirements match the ${cfg.name}'s focus on ${cfg.focus.join(" and ")} (L1).`,
      `Leans on ${cats.join(", ")}.`,
      left.length ? `Leaves out ${left.slice(0, 2).map((r) => r.title).join(" and ")}${left.length > 2 ? ` and ${left.length - 2} more` : ""}.` : "Includes every request you kept.",
    ];
    if (fallback) why.push("No comments from this market for this series: built on all markets, so confidence is lower.");

    return { id: a.id, name: a.name, tagline: a.tagline, requests: picked, why, score: { l1, l2, l3, total } };
  }).sort((x, y) => y.score.total - x.score.total);
}

/** Draft SMART target for a requirement. A PM edits it later; it is a starting point, not a commitment. */
export function draftTarget(r: FeatureRequest & { scoped: number }): string {
  const verb = r.types.defect > r.types.wants ? "Halve defect reports about" : r.types.difficult > r.types.wants ? "Halve ease-of-use complaints about" : "Deliver";
  return verb === "Deliver"
    ? `Deliver "${r.title.toLowerCase()}" at launch; check that wishes about it drop by 50% within 12 months (baseline ${r.scoped}).`
    : `${verb} ${r.title.toLowerCase()} within 12 months of launch (baseline ${r.scoped} mentions).`;
}

/** Simulated L3 social test: a stable pseudo-random share of positive reactions per profile (0.35–0.85). */
export function simulateSocial(profileIds: string[], seed: string): Record<string, number> {
  const out: Record<string, number> = {};
  for (const id of profileIds) {
    let h = 2166136261;
    for (const ch of seed + id) h = Math.imul(h ^ ch.charCodeAt(0), 16777619);
    out[id] = 0.35 + ((h >>> 0) % 500) / 1000;
  }
  return out;
}

