import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { Suspense } from "react";
import { TopBar } from "@/components/dashboard/TopBar";
import { DashboardSkeleton } from "@/components/dashboard/DashboardSkeleton";
import { Pipeline } from "@/components/pipeline/Pipeline";
import { MARKET_PARAMS, parseMarketParam } from "@/lib/dashboard-data";
import { marketById } from "@/lib/markets";
import { CAR_IMAGES } from "@/lib/car-images";
import { pipelineOrigin, seriesData } from "@/lib/pipeline/load";
import { SERIES_SLUGS, seriesBySlug } from "@/lib/pipeline/series";

export function generateStaticParams() {
  return MARKET_PARAMS.flatMap((market) => SERIES_SLUGS.map((series) => ({ market, series })));
}

export async function generateMetadata({ params }: PageProps<"/dashboard/[market]/[series]">): Promise<Metadata> {
  const { market, series } = await params;
  const scope = parseMarketParam(market);
  const cfg = seriesBySlug(series);
  if (!scope || !cfg) return { title: "Not found · Dixi" };
  return { title: `${cfg.name} · ${scope === "ALL" ? "All markets" : marketById(scope).name} · Dixi` };
}

export default function SeriesPipelinePage({ params }: PageProps<"/dashboard/[market]/[series]">) {
  return (
    <>
      <TopBar />
      <main className="mx-auto w-full max-w-[1400px] flex-1 px-4 pb-28 pt-6 sm:px-6 lg:px-8">
        <Suspense fallback={<DashboardSkeleton />}>
          <PipelineContent params={params} />
        </Suspense>
      </main>
    </>
  );
}

async function PipelineContent({ params }: Pick<PageProps<"/dashboard/[market]/[series]">, "params">) {
  const { market, series } = await params;
  const scope = parseMarketParam(market);
  const cfg = seriesBySlug(series);
  if (!scope || !cfg) notFound();
  return <Pipeline scope={scope} cfg={cfg} data={seriesData(cfg.id)} origin={pipelineOrigin()} images={CAR_IMAGES[cfg.id]} />;
}

"use client";

import { useEffect, useRef, useState } from "react";
import { REJECT_REASONS } from "@/lib/pipeline/profiles";
import type { FeatureRequest } from "@/lib/pipeline/types";

/** Modal asking why a request is rejected. A reason is required; it is saved as a decision. */
export function RejectDialog({
  request,
  onCancel,
  onConfirm,
}: {
  request: FeatureRequest | null;
  onCancel: () => void;
  onConfirm: (reason: string) => void;
}) {
  const ref = useRef<HTMLDialogElement>(null);
  const [preset, setPreset] = useState<string | null>(null);
  const [note, setNote] = useState("");

  useEffect(() => {
    const d = ref.current;
    if (!d) return;
    if (request && !d.open) {
      setPreset(null);
      setNote("");
      d.showModal();
    } else if (!request && d.open) d.close();
  }, [request]);

  const reason = [preset, note.trim()].filter(Boolean).join(": ");
  const valid = note.trim().length >= 3 || (preset !== null && note.trim().length === 0) || (preset !== null && note.trim().length >= 3);

  return (
    <dialog
      ref={ref}
      onCancel={(e) => {
        e.preventDefault();
        onCancel();
      }}
      aria-labelledby="reject-title"
      className="m-auto w-[min(520px,calc(100vw-32px))] rounded-card border border-line bg-surface p-0 text-ink shadow-float backdrop:bg-ink/30 backdrop:backdrop-blur-[2px]"
    >
      {request && (
        <form
          method="dialog"
          onSubmit={(e) => {
            e.preventDefault();
            if (valid) onConfirm(reason);
          }}
          className="flex flex-col gap-4 p-5 sm:p-6"
        >
          <div>
            <p className="text-xs font-semibold uppercase tracking-[0.12em] text-human">Reject request</p>
            <h2 id="reject-title" className="mt-1 text-lg font-semibold tracking-tight">
              Why are you rejecting “{request.title}”?
            </h2>
            <p className="mt-1 text-sm text-muted">
              Your reason is saved in Decisions with your name and the time, and it shows on every profile this request could have shaped.
            </p>
          </div>

          <fieldset>
            <legend className="sr-only">Common reasons</legend>
            <div className="flex flex-wrap gap-2">
              {REJECT_REASONS.map((r) => {
                const on = preset === r;
                return (
                  <button
                    key={r}
                    type="button"
                    aria-pressed={on}
                    onClick={() => setPreset(on ? null : r)}
                    className={`rounded-full px-3 py-1.5 text-sm transition-colors duration-150 motion-reduce:transition-none ${
                      on ? "bg-human text-white" : "bg-bg-soft text-ink-soft ring-1 ring-line hover:ring-human/40"
                    }`}
                  >
                    {r}
                  </button>
                );
              })}
            </div>
          </fieldset>

          <label className="flex flex-col gap-1.5 text-sm">
            <span className="font-medium text-ink">Explain in your words {preset ? <span className="font-normal text-muted">(optional)</span> : <span className="font-normal text-human">(required)</span>}</span>
            <textarea
              value={note}
              onChange={(e) => setNote(e.target.value)}
              rows={3}
              autoFocus
              placeholder="e.g. Our principle P1 says the car stays compact; this would add 8 cm."
              className="resize-y rounded-lg border border-line bg-surface px-3 py-2 text-sm text-ink placeholder:text-muted/70 focus:border-brand focus:outline-none"
            />
          </label>

          <div className="flex flex-col-reverse gap-2 sm:flex-row sm:justify-end">
            <button type="button" onClick={onCancel} className="h-10 rounded-full px-4 text-sm font-medium text-ink-soft ring-1 ring-line hover:bg-bg-soft">
              Cancel
            </button>
            <button
              type="submit"
              disabled={!valid}
              className="h-10 rounded-full bg-human px-5 text-sm font-medium text-white shadow-card transition-opacity disabled:cursor-not-allowed disabled:opacity-40"
            >
              Reject and save reason
            </button>
          </div>
        </form>
      )}
    </dialog>
  );
}

