export function RequestCard({
  req,
  scoped,
  scopeLabel,
  urgency,
  decision,
  onKeep,
  onReject,
  onUndo,
}: {
  req: FeatureRequest;
  scoped: number;
  scopeLabel: string;
  urgency: Urgency;
  decision?: Decision;
  onKeep: () => void;
  onReject: () => void;
  onUndo: () => void;
}) {
