  const markets = Object.entries(req.byMarket)
    .filter(([, n]) => (n ?? 0) > 0)
    .sort((a, b) => (b[1] ?? 0) - (a[1] ?? 0));

  const state = decision?.action;
  const ring = state === "keep" ? "border-good/50 ring-1 ring-good/20" : state === "reject" ? "border-line opacity-80" : "border-line";

  return (
