            <span className={`rounded-full px-2 py-0.5 text-xs font-medium capitalize ${URGENCY_CLS[urgency]}`}>{urgency} urgency</span>
            <span className="text-xs text-muted">{req.id}</span>
          </div>
          <h3 className={`mt-2 text-base font-semibold tracking-tight ${state === "reject" ? "text-muted line-through decoration-1" : "text-ink"}`}>{req.title}</h3>
          <p className="mt-0.5 text-sm text-ink-soft">{req.summary}</p>

          <div className="mt-3 flex flex-col gap-1.5">
            <div role="img" aria-label={`${wants} wishes, ${difficult} hard to use, ${defect} defects`} className="flex h-1.5 max-w-sm overflow-hidden rounded-full bg-bg-soft">
              <span className="bg-brand" style={{ width: `${(wants / typeTotal) * 100}%` }} />
              <span className="bg-wait" style={{ width: `${(difficult / typeTotal) * 100}%` }} />
              <span className="bg-bad" style={{ width: `${(defect / typeTotal) * 100}%` }} />
            </div>
            <p className="flex flex-wrap gap-x-3 text-xs text-muted">
              <span><span aria-hidden className="mr-1 inline-block size-1.5 rounded-full bg-brand align-middle" />{wants} wish it</span>
              <span><span aria-hidden className="mr-1 inline-block size-1.5 rounded-full bg-wait align-middle" />{difficult} hard to use</span>
              <span><span aria-hidden className="mr-1 inline-block size-1.5 rounded-full bg-bad align-middle" />{defect} defect</span>
            </p>
          </div>

          {req.relatedOptions.length > 0 && (
