/** Stacked bar: how much each layer contributes to a profile's score. */
export function LayerScore({ score, l3Weight }: { score: Profile["score"]; l3Weight: number }) {
  const w3 = score.l3 === null ? 0 : l3Weight;
  const w1 = 0.45 * (1 - w3);
  const w2 = 1 - w1 - w3;
  const parts = [
    { id: "L1", cls: "bg-l1", v: w1 * score.l1, label: "principles" },
    { id: "L2", cls: "bg-l2", v: w2 * score.l2, label: "evidence" },
    { id: "L3", cls: "bg-l3", v: w3 * (score.l3 ?? 0), label: "social test" },
  ];
  const pct = Math.round(score.total * 100);
  return (
    <div className="flex items-center gap-3">
      <div
        role="img"
        aria-label={`Score ${pct} of 100: ${parts.map((p) => `${p.label} ${Math.round(p.v * 100)}`).join(", ")}`}
        className="flex h-2 flex-1 overflow-hidden rounded-full bg-bg-soft ring-1 ring-inset ring-line"
      >
        {parts.map((p) => (
          <span key={p.id} className={`h-full ${p.cls}`} style={{ width: `${p.v * 100}%` }} />
        ))}
      </div>
      <span aria-hidden className="w-7 text-right text-sm font-semibold tabular-nums text-ink">
        {pct}
      </span>
    </div>
  );
}

