"use client";

import Image from "next/image";
import Link from "next/link";
import { ArrowRight, Check, Database, Loader2, Sparkles, TriangleAlert } from "lucide-react";
import { useCallback, useEffect, useMemo, useState } from "react";
import type { CarImage } from "@/lib/car-images";
import type { MarketScope } from "@/lib/dashboard-data";
import { marketById } from "@/lib/markets";
import {
  MIN_KEPT_TO_BUILD,
  URGENCY_RULE,
  buildProfiles,
  marketVolume,
  scopedMentions,
  simulateSocial,
  urgencyOf,
  type Decision,
  type Decisions,
  type Urgency,
} from "@/lib/pipeline/profiles";
import type { SeriesConfig } from "@/lib/pipeline/series";
import { CATEGORIES, type Category, type FeatureRequest, type SeriesData } from "@/lib/pipeline/types";
import { ProfileDetail, ProfileList } from "./Profiles";
import { RejectDialog } from "./RejectDialog";
import { RequestCard } from "./RequestCard";

type Stage = "analysing" | "review" | "building" | "profiles";

const STEPS: { id: Stage; label: string }[] = [
  { id: "analysing", label: "AI analysis" },
  { id: "review", label: "Your decisions" },
  { id: "building", label: "Build profiles" },
  { id: "profiles", label: "Profiles + social test" },
];

const PM = "You (PM)";

/* Decisions live in the browser for now (per market + series). */
const storageKey = (scope: MarketScope, series: string) => `dixi:decisions:${scope}:${series}`;
function readDecisions(key: string): Decisions {
  try {
    return JSON.parse(localStorage.getItem(key) ?? "{}") as Decisions;
  } catch {
    return {};
  }
}
function writeDecisions(key: string, d: Decisions) {
  try {
    localStorage.setItem(key, JSON.stringify(d));
  } catch {
    /* storage blocked: decisions stay in memory */
  }
}

export function Pipeline({
  scope,
  cfg,
  data,
  origin,
  images,
}: {
  scope: MarketScope;
  cfg: SeriesConfig;
  data: SeriesData;
  origin: "bmw" | "example";
  images?: { front: CarImage; second: CarImage };
}) {
  const scopeLabel = scope === "ALL" ? "all markets" : marketById(scope).name;
  const volume = marketVolume(data, scope);
  const fallback = scope !== "ALL" && volume === 0;
  const key = storageKey(scope, cfg.id);

  const [stage, setStage] = useState<Stage>("analysing");
  const [decisions, setDecisions] = useState<Decisions>({});
  const [category, setCategory] = useState<Category | "All">("All");
  const [urgency, setUrgency] = useState<Urgency | "all">("all");
  const [rejecting, setRejecting] = useState<FeatureRequest | null>(null);
  const [social, setSocial] = useState<Record<string, number> | null>(null);
  const [openProfile, setOpenProfile] = useState<string | null>(null);

  useEffect(() => setDecisions(readDecisions(key)), [key]);

  const decide = useCallback(
    (req: FeatureRequest, action: Decision["action"], reason?: string) =>
      setDecisions((prev) => {
        const next = { ...prev, [req.id]: { requestId: req.id, title: req.title, action, reason, by: PM, at: new Date().toISOString() } };
        writeDecisions(key, next);
        return next;
      }),
    [key],
  );
  const undo = useCallback(
    (id: string) =>
      setDecisions((prev) => {
        const next = { ...prev };
        delete next[id];
        writeDecisions(key, next);
        return next;
      }),
    [key],
  );

  const rows = useMemo(
    () =>
      data.requests
        .map((r) => {
          const scoped = scopedMentions(r, scope, fallback);
          return { req: r, scoped, urgency: urgencyOf(scoped) };
        })
        .filter((x) => x.scoped > 0)
        .sort((a, b) => b.scoped - a.scoped),
    [data.requests, scope, fallback],
  );

  const counts = useMemo(() => {
    const c = Object.fromEntries(CATEGORIES.map((k) => [k, 0])) as Record<Category, number>;
    rows.forEach((r) => (c[r.req.category] += 1));
    return c;
  }, [rows]);

  const visible = rows.filter((r) => (category === "All" || r.req.category === category) && (urgency === "all" || r.urgency === urgency));
  const kept = rows.filter((r) => decisions[r.req.id]?.action === "keep").map((r) => r.req);
  const rejectedCount = rows.filter((r) => decisions[r.req.id]?.action === "reject").length;
  const open = rows.length - kept.length - rejectedCount;

  const profiles = useMemo(
    () => (kept.length >= MIN_KEPT_TO_BUILD ? buildProfiles(kept, cfg, scope, fallback, social) : []),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [kept.map((k) => k.id).join(), cfg, scope, fallback, social],
  );

  const build = () => {
    setOpenProfile(null);
    setStage("building");
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const current = openProfile ? profiles.find((p) => p.id === openProfile) : undefined;

  return (
    <div className="flex flex-col gap-6">
      <Header cfg={cfg} scope={scope} scopeLabel={scopeLabel} volume={fallback ? marketVolume(data, "ALL") : volume} origin={origin} image={images?.front} />

      <Stepper stage={stage} canBuild={profiles.length > 0} onGo={(s) => (s === "building" ? build() : setStage(s))} />

      {fallback && (
        <div role="note" className="flex gap-3 rounded-card border border-wait/30 bg-wait-soft/60 p-4 text-sm">
          <TriangleAlert aria-hidden className="mt-0.5 size-5 shrink-0 text-wait" />
          <p className="text-ink-soft">
            <span className="font-semibold text-ink">What we don&apos;t know:</span> there are no customer comments for the {cfg.name} from {scopeLabel} in this data set. The list
            below uses every market instead, so treat it with lower confidence and check it against {scopeLabel} customer studies and sales.
          </p>
        </div>
      )}

      {stage === "analysing" && <Analysis cfg={cfg} data={data} scopeLabel={scopeLabel} rows={rows.length} volume={fallback ? marketVolume(data, "ALL") : volume} onDone={() => setStage("review")} />}

      {stage === "building" && <Building count={kept.length} onDone={() => setStage("profiles")} />}

      {stage === "review" && (
        <div className="grid gap-6 xl:grid-cols-[minmax(0,1fr)_340px]">
          <section aria-labelledby="req-heading" className="flex min-w-0 flex-col gap-4">
            <div className="flex flex-col gap-3">
              <div className="flex flex-wrap items-baseline justify-between gap-2">
                <h2 id="req-heading" className="text-lg font-semibold tracking-tight text-ink">
                  Feature requests · {cfg.name} · {scopeLabel}
                </h2>
                <p className="text-sm text-muted">Keep what should shape the next car. Every reject needs a reason.</p>
              </div>
              <div className="flex flex-col gap-2 lg:flex-row lg:items-center lg:justify-between">
                <div role="group" aria-label="Category" className="flex flex-wrap gap-1.5">
                  {(["All", ...CATEGORIES] as const).map((c) => (
                    <Chip key={c} on={category === c} onClick={() => setCategory(c)}>
                      {c} <span className="tabular-nums opacity-60">{c === "All" ? rows.length : counts[c]}</span>
                    </Chip>
                  ))}
                </div>
                <div role="group" aria-label="Urgency" className="inline-flex self-start rounded-full bg-bg-soft p-1 ring-1 ring-line">
                  {(["all", "high", "medium", "low"] as const).map((u) => (
                    <button
                      key={u}
                      type="button"
                      aria-pressed={urgency === u}
                      onClick={() => setUrgency(u)}
                      className={`rounded-full px-3 py-1 text-sm capitalize transition-colors ${urgency === u ? "bg-surface font-medium text-ink shadow-card" : "text-muted hover:text-ink"}`}
                    >
                      {u === "all" ? "Any urgency" : u}
                    </button>
                  ))}
                </div>
              </div>
              <p className="text-xs text-muted">
                Urgency = how many customers ask for it here: high from {URGENCY_RULE.high} mentions, medium from {URGENCY_RULE.medium}.
              </p>
            </div>

            {visible.length === 0 ? (
              <p className="rounded-card border border-dashed border-line p-6 text-center text-sm text-muted">No requests match these filters.</p>
            ) : (
              <ul className="flex flex-col gap-3">
                {visible.map(({ req, scoped, urgency: u }) => (
                  <RequestCard
                    key={req.id}
                    req={req}
                    scoped={scoped}
                    scopeLabel={fallback ? "all markets" : scopeLabel}
                    urgency={u}
                    decision={decisions[req.id]}
                    onKeep={() => decide(req, "keep")}
                    onReject={() => setRejecting(req)}
                    onUndo={() => undo(req.id)}
                  />
                ))}
              </ul>
            )}
          </section>

          <aside className="flex flex-col gap-6 xl:sticky xl:top-20 xl:self-start">
            <DecisionLog decisions={decisions} />
            <Context data={data} scope={scope} />
          </aside>
        </div>
      )}

      {stage === "profiles" &&
        (current ? (
          <ProfileDetail
            profile={current}
            rank={profiles.indexOf(current)}
            cfg={cfg}
            scopeLabel={scopeLabel}
            decisions={decisions}
            image={images?.second ?? images?.front}
            onBack={() => setOpenProfile(null)}
          />
        ) : (
          <ProfileList
            profiles={profiles}
            cfg={cfg}
            scopeLabel={scopeLabel}
            socialRun={social !== null}
            onOpen={(id) => {
              setOpenProfile(id);
              window.scrollTo({ top: 0, behavior: "smooth" });
            }}
            onRunSocial={() => setSocial(simulateSocial(profiles.map((p) => p.id), `${scope}-${cfg.id}`))}
          />
        ))}

      {stage === "review" && (
        <div className="fixed inset-x-0 bottom-0 z-20 border-t border-line bg-bg/95 backdrop-blur">
          <div className="mx-auto flex max-w-[1400px] flex-wrap items-center justify-between gap-3 px-4 py-3 sm:px-6 lg:px-8">
            <p className="text-sm text-ink-soft">
              <span className="font-semibold text-good">{kept.length} kept</span> · <span className="font-semibold text-bad">{rejectedCount} rejected</span> · {open} open
              {kept.length < MIN_KEPT_TO_BUILD && <span className="text-muted"> · keep at least {MIN_KEPT_TO_BUILD} to build</span>}
            </p>
            <button
              type="button"
              disabled={kept.length < MIN_KEPT_TO_BUILD}
              onClick={build}
              className="inline-flex h-10 items-center gap-2 rounded-full bg-brand px-5 text-sm font-medium text-white shadow-card transition-colors hover:bg-brand-deep disabled:cursor-not-allowed disabled:opacity-40"
            >
              <Sparkles aria-hidden className="size-4" /> Build profiles
            </button>
          </div>
        </div>
      )}

      <RejectDialog
        request={rejecting}
        onCancel={() => setRejecting(null)}
        onConfirm={(reason) => {
          if (rejecting) decide(rejecting, "reject", reason);
          setRejecting(null);
        }}
      />
    </div>
  );
}

/* ---------- pieces ---------- */

function Chip({ on, onClick, children }: { on: boolean; onClick: () => void; children: React.ReactNode }) {
  return (
    <button
      type="button"
      aria-pressed={on}
      onClick={onClick}
      className={`rounded-full px-3 py-1.5 text-sm transition-colors ${on ? "bg-ink font-medium text-white" : "bg-surface text-ink-soft ring-1 ring-line hover:ring-brand/40"}`}
    >
      {children}
    </button>
  );
}

function Header({
  cfg,
  scope,
  scopeLabel,
  volume,
  origin,
  image,
}: {
  cfg: SeriesConfig;
  scope: MarketScope;
  scopeLabel: string;
  volume: number;
  origin: "bmw" | "example";
  image?: CarImage;
}) {
  return (
    <header className="grid overflow-hidden rounded-card border border-line bg-surface shadow-card md:grid-cols-[minmax(0,1.2fr)_minmax(0,1fr)]">
      <div className="flex flex-col justify-center gap-2 p-5 sm:p-7">
        <Link href={`/dashboard/${scope.toLowerCase()}`} className="text-sm text-muted transition-colors hover:text-brand">
          <span aria-hidden>←</span> {scopeLabel}: change series
        </Link>
        <h1 className="text-2xl font-semibold tracking-tight text-ink sm:text-3xl">
          {cfg.name} <span className="text-muted">· {scopeLabel}</span>
        </h1>
        <p className="text-sm text-ink-soft">{cfg.segment}</p>
        <div className="mt-2 flex flex-wrap gap-2 text-xs">
          <span className="inline-flex items-center gap-1.5 rounded-full bg-bg-soft px-2.5 py-1 text-ink-soft ring-1 ring-line">
            <Database aria-hidden className="size-3.5" />
            {origin === "bmw" ? "BMW hackathon data (local only)" : "Example data"}
          </span>
          <span className="rounded-full bg-l2-soft px-2.5 py-1 font-medium text-l2">{volume.toLocaleString("en")} customer comments</span>
        </div>
      </div>
      {image && (
        <figure className="relative min-h-48 bg-bg-soft md:min-h-56">
          <Image src={image.src} alt={image.alt} fill priority sizes="(min-width: 768px) 45vw, 100vw" className="object-cover" />
          <figcaption className="absolute bottom-0 right-0 bg-ink/55 px-2 py-0.5 text-[0.65rem] text-white">{image.credit}</figcaption>
        </figure>
      )}
    </header>
  );
}

function Stepper({ stage, canBuild, onGo }: { stage: Stage; canBuild: boolean; onGo: (s: Stage) => void }) {
  const idx = STEPS.findIndex((s) => s.id === stage);
  return (
    <ol className="flex flex-wrap items-center gap-x-2 gap-y-2 text-sm">
      {STEPS.map((s, i) => {
        const done = i < idx;
        const active = i === idx;
        const reachable = s.id === "review" ? idx > 0 : s.id === "profiles" ? canBuild && idx >= 2 : false;
        const body = (
          <>
            <span
              className={`flex size-6 items-center justify-center rounded-full text-xs font-semibold ${
                active ? "bg-brand text-white" : done ? "bg-good-soft text-good" : "bg-bg-soft text-muted ring-1 ring-line"
              }`}
            >
              {done ? <Check aria-hidden className="size-3.5" /> : i + 1}
            </span>
            <span className={active ? "font-medium text-ink" : "text-muted"}>{s.label}</span>
          </>
        );
        return (
          <li key={s.id} className="flex items-center gap-2" aria-current={active ? "step" : undefined}>
            {reachable && !active ? (
              <button type="button" onClick={() => onGo(s.id)} className="flex items-center gap-2 rounded-full hover:underline">
                {body}
              </button>
            ) : (
              <span className="flex items-center gap-2">{body}</span>
            )}
            {i < STEPS.length - 1 && <ArrowRight aria-hidden className="size-3.5 text-line" />}
          </li>
        );
      })}
    </ol>
  );
}

/** A short, honest replay of what the AI does. The work is precomputed; the animation shows the order of the steps. */
function Analysis({
  cfg,
  data,
  scopeLabel,
  rows,
  volume,
  onDone,
}: {
  cfg: SeriesConfig;
  data: SeriesData;
  scopeLabel: string;
  rows: number;
  volume: number;
  onDone: () => void;
}) {
  const steps = [
    `L1 · Loading ${cfg.principles.length} principles for the ${cfg.name}`,
    `L2 · Reading ${volume.toLocaleString("en")} customer comments from ${scopeLabel}`,
    `L2 · Adding customer studies${data.sales.length ? ", sales volumes" : ""}${data.options.length ? ` and ${data.options.length} options from the price list` : ""}`,
    "Compressing similar comments into feature requests",
    "Sorting into Exterior · Interior · Digital · Powertrain",
    `Scoring urgency: ${rows} requests found`,
  ];
  const [done, setDone] = useState(0);

  useEffect(() => {
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const t = setInterval(() => setDone((d) => d + 1), reduce ? 120 : 520);
    return () => clearInterval(t);
  }, []);
  useEffect(() => {
    if (done > steps.length) {
      const t = setTimeout(onDone, 350);
      return () => clearTimeout(t);
    }
  }, [done, steps.length, onDone]);

  return (
    <section aria-live="polite" className="mx-auto w-full max-w-xl rounded-card border border-line bg-surface p-6 shadow-card">
      <p className="flex items-center gap-2 text-sm font-semibold text-ink">
        <Sparkles aria-hidden className="size-4 text-brand" /> Dixi is analysing the {cfg.name} for {scopeLabel}
      </p>
      <ol className="mt-4 flex flex-col gap-2.5">
        {steps.map((s, i) => (
          <li key={s} className={`flex items-center gap-2.5 text-sm transition-opacity duration-300 ${i <= done ? "opacity-100" : "opacity-30"}`}>
            {i < done ? (
              <Check aria-hidden className="size-4 text-good" />
            ) : i === done ? (
              <Loader2 aria-hidden className="size-4 animate-spin text-brand motion-reduce:animate-none" />
            ) : (
              <span aria-hidden className="size-4 rounded-full ring-1 ring-line" />
            )}
            <span className={i < done ? "text-ink-soft" : "text-ink"}>{s}</span>
          </li>
        ))}
      </ol>
      <button type="button" onClick={onDone} className="mt-5 text-xs text-muted underline-offset-2 hover:text-ink hover:underline">
        Skip
      </button>
    </section>
  );
}

function Building({ count, onDone }: { count: number; onDone: () => void }) {
  useEffect(() => {
    const t = setTimeout(onDone, 1600);
    return () => clearTimeout(t);
  }, [onDone]);
  return (
    <section aria-live="polite" className="mx-auto flex w-full max-w-xl flex-col items-center gap-3 rounded-card border border-line bg-surface p-8 text-center shadow-card">
      <Loader2 aria-hidden className="size-6 animate-spin text-brand motion-reduce:animate-none" />
      <p className="font-medium text-ink">Building profiles from your {count} kept requests</p>
      <p className="text-sm text-muted">Combining them with the L1 principles, weighing evidence (L2), leaving out everything you rejected.</p>
    </section>
  );
}

function DecisionLog({ decisions }: { decisions: Decisions }) {
  const list = Object.values(decisions).sort((a, b) => b.at.localeCompare(a.at));
  return (
    <section className="rounded-card border border-line bg-surface shadow-card">
      <h2 className="border-b border-line px-4 py-3 text-sm font-semibold text-ink">Decisions</h2>
      {list.length === 0 ? (
        <p className="px-4 py-4 text-sm text-muted">Nothing decided yet. Keep or reject requests; each decision is logged here with its reason.</p>
      ) : (
        <ul className="max-h-80 divide-y divide-line overflow-y-auto">
          {list.map((d) => (
            <li key={d.requestId} className="px-4 py-3 text-sm">
              <p className="flex items-center gap-1.5">
                <span className={`text-xs font-semibold ${d.action === "keep" ? "text-good" : "text-bad"}`}>{d.action === "keep" ? "Kept" : "Rejected"}</span>
                <span className="truncate font-medium text-ink">{d.title}</span>
              </p>
              {d.reason && <p className="mt-0.5 text-ink-soft">“{d.reason}”</p>}
              <p className="mt-0.5 text-xs text-muted">
                {d.by} · {new Date(d.at).toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" })}
              </p>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

function Context({ data, scope }: { data: SeriesData; scope: MarketScope }) {
  const studies = data.studies.filter((s) => scope === "ALL" || s.market === scope).sort((a, b) => a.score - b.score);
  const sales = data.sales.filter((s) => scope === "ALL" || s.market === scope);
  return (
    <section className="rounded-card border border-line bg-surface shadow-card">
      <h2 className="border-b border-line px-4 py-3 text-sm font-semibold text-ink">More evidence (L2)</h2>
      <div className="flex flex-col gap-4 px-4 py-4 text-sm">
        {data.strengths.length > 0 && (
          <div>
            <p className="text-xs font-semibold uppercase tracking-[0.1em] text-muted">What owners like (keep it)</p>
            <ul className="mt-1.5 flex flex-col gap-0.5">
              {data.strengths.slice(0, 5).map((s) => (
                <li key={s.title} className="flex justify-between gap-3 text-ink-soft">
                  <span>{s.title}</span>
                  <span className="tabular-nums text-muted">{s.mentions}</span>
                </li>
              ))}
            </ul>
          </div>
        )}
        <div>
          <p className="text-xs font-semibold uppercase tracking-[0.1em] text-muted">Customer study: weakest scores</p>
          {studies.length ? (
            <ul className="mt-1.5 flex flex-col gap-0.5">
              {studies.slice(0, 5).map((s) => (
                <li key={`${s.market}-${s.attribute}`} className="flex justify-between gap-3 text-ink-soft">
                  <span className="truncate">
                    {scope === "ALL" && <span className="mr-1 text-xs text-muted">{s.market}</span>}
                    {s.attribute}
                  </span>
                  <span className="tabular-nums text-muted">{s.score.toFixed(1)}</span>
                </li>
              ))}
            </ul>
          ) : (
            <p className="mt-1.5 text-muted">No study for this market and series.</p>
          )}
        </div>
        <div>
          <p className="text-xs font-semibold uppercase tracking-[0.1em] text-muted">Sales (units)</p>
          {sales.length ? (
            <table className="mt-1.5 w-full text-left tabular-nums">
              <thead className="text-xs text-muted">
                <tr>
                  <th className="font-normal">Market</th>
                  <th className="text-right font-normal">2024</th>
                  <th className="text-right font-normal">2025</th>
                  <th className="text-right font-normal">2030*</th>
                </tr>
              </thead>
              <tbody className="text-ink-soft">
                {sales.map((s) => (
                  <tr key={s.market}>
                    <td>{s.market}</td>
                    {[s.y2024, s.y2025, s.y2030].map((v, i) => (
                      <td key={i} className="text-right">
                        {v === null ? "–" : v.toLocaleString("en")}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          ) : (
            <p className="mt-1.5 text-muted">No sales figures for this market.</p>
          )}
          {sales.length > 0 && <p className="mt-1 text-xs text-muted">*2030 is a forecast.</p>}
        </div>
      </div>
    </section>
  );
}

