/* Icon vocabulary for the pipeline, so cards can stay short. Every icon has a text label for screen readers or a tooltip. */
import { Armchair, Car, Cpu, Flame, Hand, Sparkles, Swords, TrendingUp, Wrench, Zap } from "lucide-react";
import type { Urgency } from "@/lib/pipeline/profiles";
import type { Category, MarketSignal } from "@/lib/pipeline/types";

export const CATEGORY_ICON = { Exterior: Car, Interior: Armchair, Digital: Cpu, Powertrain: Zap } as const;

export const CATEGORY_TILE: Record<Category, string> = {
  Exterior: "bg-l1-soft text-l1",
  Interior: "bg-wait-soft text-wait",
  Digital: "bg-brand-soft text-brand",
  Powertrain: "bg-good-soft text-good",
};

export function CategoryTile({ category, size = "md" }: { category: Category; size?: "sm" | "md" }) {
  const Icon = CATEGORY_ICON[category];
  const box = size === "sm" ? "size-7 rounded-lg" : "size-10 rounded-xl";
  return (
    <span title={category} className={`flex shrink-0 items-center justify-center ${box} ${CATEGORY_TILE[category]}`}>
      <Icon aria-hidden className={size === "sm" ? "size-3.5" : "size-5"} />
      <span className="sr-only">{category}</span>
    </span>
  );
}

const URGENCY_CLS: Record<Urgency, string> = { high: "text-human", medium: "text-wait", low: "text-muted/60" };

/** One to three flames. */
export function UrgencyFlames({ urgency }: { urgency: Urgency }) {
  const n = urgency === "high" ? 3 : urgency === "medium" ? 2 : 1;
  return (
    <span title={`${urgency} urgency`} className={`inline-flex items-center ${URGENCY_CLS[urgency]}`}>
      {Array.from({ length: n }, (_, i) => (
        <Flame key={i} aria-hidden className="-mx-px size-3.5" fill="currentColor" />
      ))}
      <span className="sr-only">{urgency} urgency</span>
    </span>
  );
}

export const TYPE_ICON = { wants: Sparkles, difficult: Hand, defect: Wrench } as const;
export const TYPE_LABEL = { wants: "wish it", difficult: "hard to use", defect: "defect" } as const;
export const TYPE_CLS = { wants: "text-brand", difficult: "text-wait", defect: "text-bad" } as const;

export const SIGNAL_ICON = { competitor: Swords, trend: TrendingUp } as const;

export function SignalBadge({ s }: { s: MarketSignal }) {
  const Icon = SIGNAL_ICON[s.kind];
  return (
    <span
      title={`${s.kind === "competitor" ? `${s.competitor}: ` : "Trend: "}${s.title}. ${s.detail}`}
      className="inline-flex max-w-full items-center gap-1 rounded-full bg-l3-soft px-2 py-0.5 text-xs font-medium text-brand-deep ring-1 ring-l3/30"
    >
      <Icon aria-hidden className="size-3 shrink-0" />
      <span className="truncate">{s.kind === "competitor" ? s.competitor : s.title}</span>
    </span>
  );
}

"use client";

import { Check, ChevronDown, ExternalLink, Tag, Undo2, Users, X } from "lucide-react";
import { useState } from "react";
import type { Decision, Urgency } from "@/lib/pipeline/profiles";
import type { Category, FeatureRequest, MarketSignal, OptionItem } from "@/lib/pipeline/types";
import { CATEGORY_TILE, CategoryTile, SIGNAL_ICON, SignalBadge, TYPE_CLS, TYPE_ICON, TYPE_LABEL, UrgencyFlames } from "./icons";

export const CATEGORY_CLS: Record<Category, string> = CATEGORY_TILE;

export const euro = (n: number) => `€${n.toLocaleString("de-DE")}`;

export function OptionChip({ o }: { o: OptionItem }) {
  return (
    <span className="inline-flex max-w-full items-center gap-1.5 rounded-md bg-bg-soft px-2 py-1 text-xs text-ink-soft ring-1 ring-line" title={o.group}>
      <Tag aria-hidden className="size-3 shrink-0 text-muted" />
      <span className="font-mono text-[0.7rem] text-muted">{o.code}</span>
      <span className="truncate">{o.name}</span>
      <span className="shrink-0 font-medium tabular-nums text-ink">{o.priceEur === null ? "included" : euro(o.priceEur)}</span>
    </span>
  );
}

export function IconButton({ label, onClick, tone, children }: { label: string; onClick: () => void; tone: "keep" | "reject" | "plain"; children: React.ReactNode }) {
  const cls =
    tone === "keep"
      ? "bg-brand text-white shadow-card hover:bg-brand-deep"
      : tone === "reject"
        ? "text-human ring-1 ring-human/30 hover:bg-human-soft"
        : "text-muted ring-1 ring-line hover:text-ink";
  return (
    <button type="button" onClick={onClick} aria-label={label} title={label} className={`flex size-9 items-center justify-center rounded-full transition-colors ${cls}`}>
      {children}
    </button>
  );
}

export function RequestCard({
  req,
  scoped,
  scopeLabel,
  urgency,
  decision,
  signals,
  focused,
  onKeep,
  onReject,
  onUndo,
}: {
  req: FeatureRequest;
  scoped: number;
  scopeLabel: string;
  urgency: Urgency;
  decision?: Decision;
  /** Market signals (trends, competitors) that back this request. */
  signals: MarketSignal[];
  /** True while the PM looks at one of these signals. */
  focused: boolean;
  onKeep: () => void;
  onReject: () => void;
  onUndo: () => void;
}) {
  const [open, setOpen] = useState(false);
  const state = decision?.action;
  const backed = signals.length > 0;
  const markets = Object.entries(req.byMarket)
    .filter(([, n]) => (n ?? 0) > 0)
    .sort((a, b) => (b[1] ?? 0) - (a[1] ?? 0));

  const frame =
    state === "keep"
      ? "border-good/50 ring-1 ring-good/20"
      : state === "reject"
        ? "border-line opacity-70"
        : focused
          ? "border-l3 ring-2 ring-l3/40"
          : backed
            ? "border-l3/50"
            : "border-line";

  return (
    <li id={`req-${req.id}`} className={`scroll-mt-24 rounded-card border bg-surface shadow-card transition-[border-color,box-shadow,opacity] duration-200 ${frame}`}>
      <div className="flex items-center gap-3 p-3.5 sm:gap-4 sm:p-4">
        <CategoryTile category={req.category} />

        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2">
            <h3 className={`truncate font-semibold tracking-tight ${state === "reject" ? "text-muted line-through decoration-1" : "text-ink"}`}>{req.title}</h3>
            <UrgencyFlames urgency={urgency} />
          </div>
          <div className="mt-1 flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-muted">
            <span className="inline-flex items-center gap-1 font-medium text-ink-soft" title={`${scoped} mentions · ${scopeLabel}${scoped !== req.mentions ? ` (${req.mentions} in all markets)` : ""}`}>
              <Users aria-hidden className="size-3.5" />
              <span className="tabular-nums">{scoped}</span>
              <span className="sr-only">mentions in {scopeLabel}</span>
            </span>
            {(["wants", "difficult", "defect"] as const).map((k) => {
              const Icon = TYPE_ICON[k];
              return (
                <span key={k} className="inline-flex items-center gap-1 tabular-nums" title={`${req.types[k]} ${TYPE_LABEL[k]}`}>
                  <Icon aria-hidden className={`size-3.5 ${TYPE_CLS[k]}`} />
                  {req.types[k]}
                  <span className="sr-only">{TYPE_LABEL[k]}</span>
                </span>
              );
            })}
            {req.relatedOptions.length > 0 && (
              <span className="inline-flex items-center gap-1" title="Related options on today's price list">
                <Tag aria-hidden className="size-3.5" />
                {req.relatedOptions.length}
                <span className="sr-only">related options</span>
              </span>
            )}
            {signals.slice(0, 3).map((s) => (
              <SignalBadge key={s.id} s={s} />
            ))}
          </div>
        </div>

        {state ? (
          <div className="flex shrink-0 items-center gap-2">
            <span
              title={decision?.reason ? `Why: ${decision.reason}` : undefined}
              className={`inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-xs font-medium ${state === "keep" ? "bg-good-soft text-good" : "bg-bad-soft text-bad"}`}
            >
              {state === "keep" ? <Check aria-hidden className="size-3.5" /> : <X aria-hidden className="size-3.5" />}
              {state === "keep" ? "Kept" : "Rejected"}
            </span>
            <IconButton label="Undo" tone="plain" onClick={onUndo}>
              <Undo2 aria-hidden className="size-4" />
            </IconButton>
          </div>
        ) : (
          <div className="flex shrink-0 gap-2">
            <IconButton label={`Reject: ${req.title}`} tone="reject" onClick={onReject}>
              <X aria-hidden className="size-4" />
            </IconButton>
            <IconButton label={`Keep: ${req.title}`} tone="keep" onClick={onKeep}>
              <Check aria-hidden className="size-4" />
            </IconButton>
          </div>
        )}

        <button
          type="button"
          aria-expanded={open}
          aria-label={open ? "Hide evidence" : "Show evidence"}
          title="Evidence"
          onClick={() => setOpen((v) => !v)}
          className="flex size-8 shrink-0 items-center justify-center rounded-full text-muted hover:bg-bg-soft hover:text-ink"
        >
          <ChevronDown aria-hidden className={`size-4 transition-transform ${open ? "rotate-180" : ""}`} />
        </button>
      </div>

      {state === "reject" && decision?.reason && (
        <p className="mx-4 mb-3 rounded-lg bg-bad-soft/60 px-3 py-1.5 text-xs text-ink-soft">
          <span className="font-semibold text-bad">Why:</span> {decision.reason}
        </p>
      )}

      {open && (
        <div className="flex flex-col gap-4 border-t border-line px-4 py-4 text-sm">
          <p className="text-ink-soft">{req.summary}</p>

          {req.relatedOptions.length > 0 && (
            <div className="flex flex-wrap gap-1.5">
              {req.relatedOptions.map((o) => (
                <OptionChip key={o.code} o={o} />
              ))}
            </div>
          )}

          {backed && (
            <ul className="flex flex-col gap-1.5">
              {signals.map((s) => {
                const Icon = SIGNAL_ICON[s.kind];
                return (
                  <li key={s.id} className="flex items-start gap-2 text-ink-soft">
                    <Icon aria-hidden className="mt-0.5 size-4 shrink-0 text-l3" />
                    <span>
                      <span className="font-medium text-ink">{s.kind === "competitor" ? `${s.competitor}: ${s.title}` : s.title}.</span> {s.detail}{" "}
                      {s.sources.slice(0, 1).map((src) => (
                        <a key={src.url} href={src.url} target="_blank" rel="noreferrer" className="inline-flex items-center gap-0.5 text-xs text-brand hover:underline">
                          {src.label}
