const letter = (i: number) => String.fromCharCode(65 + i);

export function ProfileList({ profiles, cfg, onOpen }: { profiles: Profile[]; cfg: SeriesConfig; onOpen: (id: string) => void }) {
  return (
    <ul className="grid gap-4 lg:grid-cols-3">
      {profiles.map((p, i) => (
        <li key={p.id}>
          <article className={`flex h-full flex-col rounded-card border bg-surface p-5 shadow-card ${i === 0 ? "border-brand/50 ring-2 ring-brand/10" : "border-line"}`}>
            <div className="flex items-center justify-between gap-3">
              <p className="flex items-center gap-2 text-xs font-semibold uppercase tracking-[0.12em] text-muted">
                <span aria-hidden className={`size-2.5 rounded-full ${PROFILE_COLOR[p.id].bg}`} />
                Profile {letter(i)}
              </p>
              {i === 0 && (
                <span className="inline-flex items-center gap-1 rounded-full bg-brand-soft px-2 py-0.5 text-xs font-medium text-brand-deep">
                  <Trophy aria-hidden className="size-3" /> Best fit
                </span>
              )}
            </div>
            <h3 className="mt-1.5 text-lg font-semibold tracking-tight text-ink">{p.name}</h3>
            <p className="text-sm text-ink-soft">{p.tagline}</p>
            <div className="mt-4">
              <LayerScore score={p.score} l3Weight={cfg.l3Weight} />
            </div>
            <ul className="mt-4 flex flex-1 flex-col gap-2 text-sm">
              {p.requests.slice(0, 5).map((r) => (
                <li key={r.id} className="flex items-center gap-2.5">
                  <CategoryTile category={r.category} size="sm" />
                  <span className="min-w-0 flex-1 truncate text-ink-soft">{r.title}</span>
                  <span className="shrink-0 text-xs tabular-nums text-muted">#{r.priority}</span>
                </li>
              ))}
              {p.wishes.map((w) => (
                <li key={w.id} className="flex items-center gap-2.5">
                  <span className="flex size-7 shrink-0 items-center justify-center rounded-lg bg-brand-soft text-brand">
                    <Star aria-hidden className="size-3.5" fill="currentColor" />
                  </span>
                  <span className="min-w-0 flex-1 truncate text-brand-deep">{w.title}</span>
                </li>
              ))}
            </ul>
            <button
              type="button"
              onClick={() => onOpen(p.id)}
              className="mt-5 inline-flex h-10 items-center justify-center gap-1.5 rounded-full text-sm font-medium text-ink ring-1 ring-line transition-colors hover:bg-bg-soft hover:ring-brand/30"
            >
              Open profile <ArrowRight aria-hidden className="size-4" />
            </button>
          </article>
        </li>
      ))}
    </ul>
  );
}

export function ProfileDetail({
  profile,
  rank,
  cfg,
  scopeLabel,
  decisions,
  image,
  onBack,
}: {
  profile: Profile;
  rank: number;
  cfg: SeriesConfig;
  scopeLabel: string;
  decisions: Decisions;
  image?: CarImage;
  onBack: () => void;
}) {
  const included = new Set(profile.requests.map((r) => r.id));
  const all = Object.values(decisions);
  const rejected = all.filter((d) => d.action === "reject");
  const keptOut = all.filter((d) => d.action === "keep" && !included.has(d.requestId));
  const options = profile.requests.flatMap((r) => r.relatedOptions);
  const optionTotal = options.reduce((s, o) => s + (o.priceEur ?? 0), 0);
  const covered = profile.requests.reduce((s, r) => s + r.scoped, 0);
  const signals = [...profile.wishes.map((s) => ({ s, wish: true })), ...profile.backing.filter((b) => !profile.wishes.includes(b)).map((s) => ({ s, wish: false }))];
  const today = new Date().toLocaleDateString("en-GB", { dateStyle: "long" });

  return (
    <div className="flex flex-col gap-5">
      <div data-no-print className="flex items-center justify-between gap-3">
        <button type="button" onClick={onBack} className="inline-flex items-center gap-1.5 text-sm text-muted hover:text-brand">
          <ArrowLeft aria-hidden className="size-4" /> All profiles
        </button>
        <button
          type="button"
          onClick={() => window.print()}
          title="Opens the print dialog: choose “Save as PDF”"
          className="inline-flex h-10 items-center gap-2 rounded-full bg-ink px-4 text-sm font-medium text-white shadow-card transition-colors hover:bg-brand-deep"
        >
          <Download aria-hidden className="size-4" /> Download PDF
        </button>
      </div>

      <div data-print-root className="flex flex-col gap-5">
        <div data-print-only className="mb-2 border-b border-line pb-3">
          <p className="text-lg font-semibold text-brand-deep">Dixi · Profile report</p>
          <p className="text-xs text-muted">
            {cfg.name} · {scopeLabel} · Profile {letter(rank)} · {today}
          </p>
        </div>

        <CarBanner image={image}>
          <p className="flex items-center gap-2 text-xs font-semibold uppercase tracking-[0.16em] text-brand-sky">
            <span aria-hidden className={`size-2.5 rounded-full ${PROFILE_COLOR[profile.id].bg}`} />
            Profile {letter(rank)} · {cfg.name} · {scopeLabel}
          </p>
          <h2 className="text-3xl font-semibold tracking-tight sm:text-4xl">{profile.name}</h2>
          <p className="text-white/70">{profile.tagline}</p>
          <div className="mt-1 flex flex-wrap gap-2">
            <BannerStat value={Math.round(profile.score.total * 100)} label="score" />
            <BannerStat value={Math.round(profile.score.l1 * 100)} label="L1 fit" />
            <BannerStat value={Math.round(profile.score.l2 * 100)} label="L2 coverage" />
            <BannerStat value={profile.score.l3 === null ? "–" : Math.round(profile.score.l3 * 100)} label="L3 social" />
          </div>
        </CarBanner>

        <dl className="grid grid-cols-2 gap-3 md:grid-cols-4">
          <Kpi icon={<ListChecks aria-hidden className="size-4" />} label="Requirements" value={profile.requests.length} />
          <Kpi icon={<MessageSquareText aria-hidden className="size-4" />} label="Customer mentions covered" value={covered.toLocaleString("en")} />
          <Kpi icon={<Tag aria-hidden className="size-4" />} label="Related options today" value={optionTotal ? euro(optionTotal) : "–"} />
          <Kpi icon={<Star aria-hidden className="size-4" />} label="From your wishlist" value={profile.wishes.length} />
        </dl>

        <Section title="Requirements" hint="In your priority order">
          <ol className="divide-y divide-line">
            {profile.requests.map((r) => (
              <li key={r.id} className="grid grid-cols-[2.25rem_1fr] gap-3 px-5 py-3.5 sm:grid-cols-[2.25rem_1fr_auto]">
                <CategoryTile category={r.category} size="sm" />
                <div className="min-w-0">
                  <p className="flex flex-wrap items-baseline gap-x-2 font-medium text-ink">
                    <span className="text-xs tabular-nums text-muted">#{r.priority}</span>
                    {r.title}
                  </p>
                  <p className="mt-0.5 text-sm text-ink-soft">{draftTarget(r).replace(/^“[^”]+”: /, "")}</p>
                  {r.relatedOptions.length > 0 && (
                    <p className="mt-1 flex flex-wrap gap-x-3 gap-y-0.5 text-xs text-muted">
                      {r.relatedOptions.map((o) => (
                        <span key={o.code} className="inline-flex items-center gap-1">
                          <Tag aria-hidden className="size-3" />
                          <span className="font-mono">{o.code}</span> {o.name} · {o.priceEur === null ? "included" : euro(o.priceEur)}
                        </span>
                      ))}
                    </p>
                  )}
                </div>
                <p className="col-start-2 text-sm tabular-nums text-muted sm:col-start-3 sm:text-right">
                  <span className="font-semibold text-ink">{r.scoped}</span> mentions
                </p>
              </li>
            ))}
          </ol>
        </Section>

        <div className="grid gap-5 lg:grid-cols-2">
          <Section title="Why the agent chose this profile">
            <ul className="flex flex-col gap-2 px-5 py-4 text-sm text-ink-soft">
              {profile.why.map((w) => (
                <li key={w} className="flex gap-2">
                  <Check aria-hidden className="mt-0.5 size-4 shrink-0 text-good" />
                  {w}
                </li>
              ))}
            </ul>
          </Section>
          <Section title="L1 principles respected" icon={<ShieldCheck aria-hidden className="size-4 text-l1" />}>
            <ul className="flex flex-col gap-3 px-5 py-4 text-sm">
              {cfg.principles.map((p) => (
                <li key={p.id} className="flex gap-2.5">
                  <span className="mt-px font-mono text-xs font-semibold text-l1">{p.id}</span>
                  <span>
                    <span className="text-ink-soft">{p.text}</span>
                    <span className="block text-xs text-muted">Owner: {p.owner}</span>
                  </span>
                </li>
              ))}
            </ul>
          </Section>
        </div>

        <Section title="Competitors & trends" icon={<Radar aria-hidden className="size-4 text-l3" />}>
          {signals.length === 0 ? (
            <p className="px-5 py-4 text-sm text-muted">No competitor or trend signal is linked to this profile.</p>
          ) : (
            <ul className="grid gap-px bg-line sm:grid-cols-2">
              {signals.map(({ s, wish }) => {
                const Icon = wish ? Star : SIGNAL_ICON[s.kind];
                return (
                  <li key={s.id} className="flex gap-3 bg-surface px-5 py-3 text-sm">
                    <Icon aria-hidden className={`mt-0.5 size-4 shrink-0 ${wish ? "text-brand" : "text-l3"}`} fill={wish ? "currentColor" : "none"} />
                    <div className="min-w-0">
                      <p className="font-medium text-ink">{s.kind === "competitor" ? `${s.competitor}: ${s.title}` : s.title}</p>
                      <p className="text-ink-soft">{s.detail}</p>
                      <p className="mt-0.5 flex flex-wrap items-center gap-x-2 text-xs text-muted">
                        {wish ? "From your wishlist" : `Backs: ${s.relatesTo.join(", ")}`}
                        {s.sources.slice(0, 1).map((src) => (
                          <a key={src.url} href={src.url} target="_blank" rel="noreferrer" className="inline-flex items-center gap-0.5 text-brand hover:underline">
                            {src.label}
                            <ExternalLink aria-hidden className="size-3" />
                          </a>
                        ))}
                      </p>
                    </div>
                  </li>
                );
              })}
            </ul>
          )}
        </Section>

        <Section title="Decision trail" hint="Every decision that shaped this profile">
          {rejected.length === 0 && keptOut.length === 0 ? (
            <p className="px-5 py-4 text-sm text-muted">No rejections. Every request you kept is in this profile.</p>
          ) : (
            <ul className="divide-y divide-line">
              {rejected.map((d) => (
                <li key={d.requestId} className="flex gap-3 px-5 py-3 text-sm">
                  <X aria-hidden className="mt-0.5 size-4 shrink-0 text-bad" />
                  <div>
                    <p className="font-medium text-ink">Rejected: {d.title}</p>
                    <p className="text-ink-soft">“{d.reason}”</p>
                    <p className="text-xs text-muted">
                      {d.by} · {new Date(d.at).toLocaleString("en-GB", { dateStyle: "medium", timeStyle: "short" })}
                    </p>
                  </div>
                </li>
              ))}
              {keptOut.map((d) => (
                <li key={d.requestId} className="flex gap-3 px-5 py-3 text-sm">
                  <Check aria-hidden className="mt-0.5 size-4 shrink-0 text-muted" />
                  <p className="text-ink-soft">
                    Kept, but in another profile: <span className="font-medium text-ink">{d.title}</span>
                  </p>
                </li>
              ))}
            </ul>
          )}
        </Section>

        <p className="text-xs text-muted">
          Evidence: BMW customer feedback, customer studies, sales and the German option list (July 2026). Competitor and trend signals link their public sources. Principles
          and competitor notes are example content; the social test is simulated. {image && `${image.credit}, modified.`}
        </p>
      </div>
    </div>
  );
}

function Kpi({ icon, label, value }: { icon: React.ReactNode; label: string; value: React.ReactNode }) {
  return (
    <div className="rounded-card border border-line bg-surface p-4 shadow-card">
      <dt className="flex items-center gap-1.5 text-xs text-muted">
        {icon}
        {label}
      </dt>
      <dd className="mt-1 text-2xl font-semibold tracking-tight tabular-nums text-ink">{value}</dd>
    </div>
  );
}

function Section({ title, hint, icon, children }: { title: string; hint?: string; icon?: React.ReactNode; children: React.ReactNode }) {
  return (
    <section className="overflow-hidden rounded-card border border-line bg-surface shadow-card">
      <div className="flex items-baseline justify-between gap-3 border-b border-line px-5 py-3">
        <h3 className="flex items-center gap-2 text-sm font-semibold text-ink">
          {icon}
          {title}
        </h3>
        {hint && <p className="text-xs text-muted">{hint}</p>}
      </div>
      {children}
    </section>
  );
}
